window.NOTES={"version":47,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":10,"chapter":5,"section":"5.1","type":"单选","topic":"视图","title":"浏览、普通、备注页和阅读视图的用途","trigger":"题目要求选择便于批量添加、删除和移动幻灯片的视图。","conclusion":"普通视图编辑幻灯片，浏览视图管理整套页面，备注页视图排版说明，阅读视图侧重播放；当前视图决定可操作的对象。","points":["普通视图适合编辑单张幻灯片的文字、图片等对象，下方备注窗格还可输入该页的演讲备注。","幻灯片浏览视图把整套页面显示为缩略图，便于拖动重排、批量选择和设置切换；修改某张幻灯片里的文字应返回普通视图。","阅读视图和放映视图主要用于观看；阅读视图提供翻页控件，幻灯片放映用于向观众演示，不能把二者当作正文编辑区。","备注页视图用于编辑备注并安排打印版式，可调整幻灯片缩略图的位置、大小，或在备注页补充图片；不能在缩略图内部直接改幻灯片正文。删除这里的缩略图只删备注页中的图像，不删除源幻灯片。"],"boundary":"浏览视图擅长结构管理，不适合精细编辑单个对象。","id":"y2020q10","sources":[{"year":2020,"q":10,"type":"单选"},{"year":2022,"q":12,"type":"单选"}],"keys":["2020-10","2022-12"],"related":[{"id":"y2020q12","label":"删除幻灯片要选中缩略图，隐藏不等于删除","reason":"批量删页或隐藏页先在缩略图或浏览视图选中整页，放映画面不代表整页已选中。"},{"id":"y2024q46","label":"默认打开视图在PowerPoint选项中设置","reason":"当前视图按钮只切换本窗口，默认打开视图需另设应用首选项。"}],"pointGroups":null},{"q":45,"chapter":5,"section":"5.1","type":"填空","topic":"文件格式","title":"ppsx是PowerPoint放映文件扩展名","trigger":"题目要求填写PowerPoint 2016放映文件的扩展名。","conclusion":".ppsx是PowerPoint放映格式，双击通常直接进入放映；.pptx是普通可编辑演示文稿格式。","points":[".potx是演示文稿模板。",".ppsm和.pptm是可包含宏的格式。","ppsx仍可在PowerPoint中打开并进入编辑界面。"],"boundary":"放映格式不是不可编辑或加密格式；它主要改变默认打开行为。","id":"y2023q45","sources":[{"year":2023,"q":45,"type":"填空"}],"keys":["2023-45"],"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"扩展名影响打开关联，但改后缀不转换内容，也不能提供编辑保护。"},{"id":"y2024q46","label":"默认打开视图在PowerPoint选项中设置","reason":"放映文件的默认双击行为与应用的默认编辑视图是两个层次。"}]},{"q":46,"chapter":5,"section":"5.1","type":"填空","topic":"PowerPoint选项","title":"默认打开视图在PowerPoint选项中设置","trigger":"题目要求把演示文稿打开时的默认视图设置为幻灯片浏览视图。","conclusion":"PowerPoint2016在文件→选项→高级→显示的“使用此视图打开所有文档”列表中设置默认打开视图，选择后单击“确定”。","points":["这是应用级首选项，不是当前幻灯片上的对象。","状态栏视图按钮只切换当前窗口视图。","设置后单击“确定”，再打开文档验证指定视图；若只是暂时切到浏览视图，不会改写这个应用级默认选项。"],"boundary":"把文件保存时停在浏览视图不等于设置所有文档的默认打开视图。","id":"y2024q46","sources":[{"year":2024,"q":46,"type":"填空"}],"keys":["2024-46"],"related":[{"id":"y2020q10","label":"浏览、普通、备注页和阅读视图的用途","reason":"先按编辑单页、管理顺序或观看放映的用途选择合适默认视图。"},{"id":"y2023q45","label":"ppsx是PowerPoint放映文件扩展名","reason":"ppsx双击进入放映属于文件打开行为，不应与普通文稿的视图首选项混淆。"}],"pointGroups":null},{"q":12,"chapter":5,"section":"5.2","type":"单选","topic":"幻灯片删除与隐藏","title":"删除幻灯片要选中缩略图，隐藏不等于删除","trigger":"真题从隐藏状态、编辑视图和阅读视图考查整张幻灯片的删除边界。","conclusion":"普通视图缩略图窗格和幻灯片浏览视图可选中整页后删除；隐藏则保留源幻灯片，只让常规顺序放映跳过它。","points":["删除整页会从演示文稿中移除该页；隐藏仍保留内容、对象和已有动画供编辑。","Delete作用于当前选择：选缩略图是删除页面，选页内对象是删除对象，文字光标状态下则编辑文字。","隐藏页在缩略图编号处有隐藏标记；取消隐藏会恢复其参与常规顺序放映的资格。","隐藏页面仍可通过特定链接或放映导航访问；隐藏不等于无法打开。","阅读视图和放映视图主要用于观看，不是常规编辑删除入口。","放映黑屏只是临时遮住观众画面，不会把当前幻灯片设置为隐藏。"],"boundary":"“正在看到一张幻灯片”不等于已选中整页；所有隐藏或删除操作都应跟随当前真实选择，不能固定作用于示例中的某一页。","id":"y2020q12","sources":[{"year":2020,"q":12,"type":"单选"},{"year":2023,"q":12,"type":"单选"}],"keys":["2020-12","2023-12"],"comparison":{"headers":["操作","改变的状态","源页面"],"rows":[["隐藏幻灯片","常规放映跳过","保留"],["删除缩略图","从文件移除整页","移除"],["从自定义放映移除","某方案不再引用该页","保留"],["放映黑屏","临时遮蔽观众画面","保留"]]},"related":[{"id":"y2020q10","label":"浏览、普通、备注页和阅读视图的用途","reason":"删除整张幻灯片前需进入可编辑视图并选中缩略图，避免误删页内对象。"},{"id":"y2026q55","label":"从自定义放映中移除不等于删除幻灯片","reason":"自定义放映移除的是方案引用，隐藏改变常规放映资格，删除才移除源页。"},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"隐藏页仍可通过动作或超链接访问，因此隐藏不等于断开导航入口。"}],"pointGroups":[{"title":"在编辑视图选对对象再删除","indices":[0,1,4]},{"title":"隐藏页面、导航访问与临时黑屏","indices":[2,3,5]}]},{"q":10,"target":null,"page":3,"chapter":5,"section":"5.2","topic":"空白幻灯片输入","title":"幻灯片文字需要文本框、占位符或形状等载体","conclusion":"空白版式没有现成文本占位符；先插入文本框等对象，再在对象中输入文字。","points":["“插入→文本框”后在幻灯片上单击或拖出区域，即可输入文字。","艺术字、公式、表格和可添加文字的形状也是对象，不是直接把文字写到背景上。","单击背景不等于创建文本插入点；要观察对象边框和闪烁光标。","标题和内容版式含占位符，与空白版式不同。"],"boundary":"不能把网页演示中的输入框误记为PowerPoint背景自带输入区；先有承载对象，再编辑对象文字。","type":"单选","trigger":"围绕空白幻灯片输入的识别、应用与易错边界整理。","id":"y2021q10","sources":[{"year":2021,"q":10,"type":"单选"}],"keys":["2021-10"],"related":[{"id":"y2026q54","label":"占位符文本可自动适应边界","reason":"文本进入占位符后才涉及自动适应边界，普通文本框与占位符的规则仍有差异。"},{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"占位符来自所用版式，母版和版式的继承关系解释不同页面为何有不同输入区域。"}]},{"q":72,"target":null,"chapter":5,"section":"5.2","topic":"从大纲导入","title":"Word标题层级决定导入PowerPoint后的幻灯片结构","conclusion":"先给Word内容设置标题层级，再在PowerPoint“开始→新建幻灯片→幻灯片（从大纲）”导入。","points":["每个“标题1”建立一张新幻灯片并成为页标题；其后的“标题2”进入这张幻灯片的正文，直到遇见下一个“标题1”。标题和正文归错页时，先修正Word大纲层级。","导入前保存并关闭Word源文件，在PowerPoint选择该文件；常规Windows流程可使用.docx。源文件仍在Word中打开时，应先关闭再导入，不能只切换窗口。","把Word文档作为对象插入，只得到一个对象，不会按标题拆成多张幻灯片。"],"boundary":"只加粗放大不保证建立大纲层级；导入后应检查正文归属和版面。","type":"综合","trigger":"从从大纲导入的判断与应用整理。","id":"y2022q72","sources":[{"year":2022,"q":72,"type":"综合"}],"keys":["2022-72"],"related":[{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"导入前必须先建立Word标题层级，手工加粗放大不会自动形成幻灯片结构。"},{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"统一应用并修改标题样式，可同时规范Word外观与大纲导入所需的层级。"}],"pointGroups":null},{"q":64,"chapter":5,"section":"5.2","type":"操作","topic":"SmartArt操作","title":"SmartArt要先辨认选择层级，再改形状、层级或链接","trigger":"真题从更改形状、升降级和给单个节点链接本地文件考查SmartArt对象层级。","conclusion":"先确认选中的是目标形状边框，再按任务使用“更改形状”“升级/降级”或插入超链接；文字光标与整体外框作用范围不同。","points":["降级改变层级，下移只改变同级顺序。","给单个节点链接应选形状边框，再选现有文件或网页。","本地文件链接依赖路径，移动文件后可能失效。","在SmartArt目标节点后新增同级形状，可选中该节点，再用“SmartArt工具→设计→添加形状→在后面添加形状”；在形状内部按Enter通常增加段落，不等同于新增节点。","更改节点为圆角矩形：选中目标形状边框→SmartArt工具→格式→更改形状→圆角矩形。"],"boundary":"选中文字可能只链接文字，选中整体外框可能作用于整个SmartArt；必须观察选择框。","id":"y2025q53","sources":[{"year":2023,"q":64,"type":"操作"},{"year":2023,"q":65,"type":"操作"},{"year":2024,"q":63,"type":"操作"},{"year":2025,"q":53,"type":"操作"},{"year":2021,"q":53,"type":"操作","page":9}],"keys":["2023-64","2023-65","2024-63","2025-53","2021-53"],"related":[{"id":"y2021q10","label":"幻灯片文字需要文本框、占位符或形状等载体","reason":"文字光标、单个对象边框与整体外框的选择层级不同，会决定编辑作用范围。"},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"节点超链接或动作负责目标跳转，页内对象动画不能替代跳转设置。"},{"id":"y2024q26","label":"艺术字是可旋转、填充和组合的图形对象","reason":"SmartArt节点、普通形状和艺术字保留不同编辑能力，转换前先辨认对象类型。"}],"pointGroups":[{"title":"调整节点层级、顺序或新增节点","indices":[0,3]},{"title":"给单个节点建立有效链接","indices":[1,2]},{"title":"选中节点外框后更改形状","indices":[4]}]},{"q":12,"chapter":5,"section":"5.2","type":"单选","topic":"新建幻灯片","title":"Ctrl+M新建幻灯片，Ctrl+N新建演示文稿","trigger":"题目要求辨认PowerPoint中哪些操作能插入新幻灯片。","conclusion":"Ctrl+M在当前演示文稿中插入新幻灯片；Ctrl+N创建新的演示文稿窗口。","points":["“开始→新建幻灯片”可选择版式后插入。","在缩略图窗格右键可选择“新建幻灯片”。","复制幻灯片适合保留现有版式和内容结构。"],"boundary":"新建演示文稿、新建幻灯片和复制幻灯片是三个不同层级的动作。","id":"y2024q12","sources":[{"year":2024,"q":12,"type":"单选"}],"keys":["2024-12"],"related":[{"id":"y2020q10","label":"浏览、普通、备注页和阅读视图的用途","reason":"新建单页后在普通视图编辑，浏览视图则适合管理整套页面顺序。"},{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"新建幻灯片要选择版式，占位符和共用外观取决于版式所属母版。"}]},{"q":13,"chapter":5,"section":"5.2","type":"单选","topic":"节管理与导航","title":"PowerPoint的节用于组织，导航最终定位幻灯片","trigger":"真题从新增、折叠、重命名和放映定位考查PowerPoint节。","conclusion":"节为幻灯片分组，便于编辑和协作；放映时可借助缩略图或节入口导航，但最终显示的仍是具体幻灯片。","points":["点击节名旁的三角可折叠或展开该节，只改变缩略图窗格的显示，不删除其中幻灯片。","节标题本身不是幻灯片。","要在放映时到达某节，最终仍需定位该节中的幻灯片；Windows放映中可输入目标幻灯片编号后按Enter。节名没有独立的放映页码。","点击节标题可选中该节的幻灯片，再设置统一切换效果；只选节内第一页不会自动影响所有页面。“全部应用”则影响整套文稿。","节可包含多张幻灯片，并可整体移动、折叠或展开；同一演示文稿的幻灯片方向通常统一，不能仿照Word给不同节设置不同纸张方向。"],"boundary":"不能把节、幻灯片和自定义放映混为一谈。","id":"y2025q10","sources":[{"year":2024,"q":13,"type":"单选"},{"year":2025,"q":10,"type":"单选"},{"year":2022,"q":64,"type":"操作"},{"year":2021,"q":26,"type":"多选","page":5}],"keys":["2024-13","2025-10","2022-64","2021-26"],"related":[{"id":"y2026q55","label":"从自定义放映中移除不等于删除幻灯片","reason":"节按编辑结构分组，自定义放映保存播放清单与顺序，二者不能互相替代。"},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"给整节统一切换需先选中该节全部页面，切换效果仍属于每张具体幻灯片。"},{"id":"y2020q61","label":"只改变一页纸张方向","reason":"Word节可分别控制纸张方向，PowerPoint节主要组织页面，跨应用不能照搬能力。"}],"pointGroups":[{"title":"节怎样组织页面与导航","indices":[0,1,2,4]},{"title":"选中整节后统一设置切换","indices":[3]}]},{"q":26,"chapter":5,"section":"5.2","type":"多选","topic":"艺术字","title":"艺术字是可旋转、填充和组合的图形对象","trigger":"题目判断PowerPoint艺术字的旋转、转换、组合编辑和纹理填充能力。","conclusion":"艺术字可通过旋转手柄任意旋转，可设置文字填充与效果，也可与其他对象组合；组合后仍可进入组内选择单个对象编辑。","points":["选中艺术字外框后拖旋转手柄可旋转整个对象；拖动时按住Shift，以15°为步长约束角度。要求精确角度时，也可在旋转的更多选项中输入数值。","纹理用于文字填充时作用于字形内部，不是对象背景。","普通文本可转换为SmartArt；SmartArt也可转换为形状，但这与把艺术字对象整体直接转换为SmartArt不是同一动作。"],"boundary":"“组合”不等于熔成一张图片；组内对象仍保持独立属性，可通过再次单击或选择窗格定位。","id":"y2024q26","sources":[{"year":2024,"q":26,"type":"多选"}],"keys":["2024-26"],"related":[{"id":"y2022q54","label":"用艺术字创建弯曲、描边和填充的装饰文字","reason":"艺术字的填充、轮廓和转换作用于文字对象，可把Word中的对象格式思路迁移过来。"},{"id":"y2026q36","label":"形状可以与图片、艺术字组合","reason":"组合保留成员的编辑属性，选外框、进入组内与编辑文字应按目标切换。"}],"pointGroups":null},{"q":53,"chapter":5,"section":"5.2","type":"操作","topic":"替换图片","title":"更改图片可保留对象的大部分效果","trigger":"题目要求替换图片内容，同时尽量保留原对象的动画。","conclusion":"选中图片后使用“更改图片”，通常可以保留其位置、大小、格式和已设置动画。","points":["选中原图片→图片工具→格式→更改图片→选择新图片。直接删除再插入会创建新对象，原动画通常丢失；替换后可在动画窗格核对原对象的效果是否保留。","替换后应检查裁剪比例和清晰度。","选择窗格可帮助确认替换的是正确对象。","“更改图片”替换图片来源；“重设图片”重置图片的格式或裁剪等设置，不负责换成另一张源图片。"],"boundary":"不同来源图片比例差异较大时，部分裁剪效果可能需要重新调整。","id":"y2026q53","sources":[{"year":2026,"q":53,"type":"操作"}],"keys":["2026-53"],"related":[{"id":"merged-9","label":"图片尺寸、纵横比与裁剪","reason":"替换图片后纵横比可能不同，需检查裁剪和缩放是否保持主体不变形。"},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"动画附着于页内对象，删除重插会建立新对象，可能失去原有动画设置。"}],"pointGroups":null},{"q":54,"chapter":5,"section":"5.2","type":"操作","topic":"文本自适应","title":"占位符文本可自动适应边界","trigger":"题目要求在不改变占位符大小的情况下容纳更多文字。","conclusion":"要求保持占位符大小时，应让溢出的文字缩小；“调整形状大小以适应文字”扩大的是外框。先确认选中的是正文占位符还是普通文本框，再找对应入口。","points":["正文占位符开始溢出时，左下角出现自动调整菜单，可选“根据占位符自动调整文本”。“调整形状大小以适应文字”在设置形状格式→文本选项→文本框中，它扩大外框，不能满足“不改变占位符大小”的要求。","普通文本框没有占位符左下角的这个菜单，但仍可右击文本框外框→设置形状格式→文本选项→文本框，选择溢出时缩小文字的选项。没有小图标不等于不能自动缩小。","自动缩小按各段文字原有字号的比例缩放，不是把原本不同字号强制设成同一个字号；还可能压缩按比例设置的行距。操作后同时检查文字是否完整、外框是否保持和实际可读性。","文字过多时可精简或拆分幻灯片。正文占位符菜单的“拆分为两张幻灯片”会把已有内容分到两页；“在新幻灯片上继续”保留原页文字，另建一页供继续输入。"],"boundary":"“能放下”不等于“适合演示”，字号过小会降低现场可读性。","id":"y2026q54","sources":[{"year":2026,"q":54,"type":"操作"}],"keys":["2026-54"],"searchAliases":["文字放不下","字超出框","文字溢出","自动缩小字号"],"related":[{"id":"y2021q10","label":"幻灯片文字需要文本框、占位符或形状等载体","reason":"先确认文字位于占位符还是普通文本框，自动调整选项与边界行为可能不同。"},{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"占位符结构来自版式，页面异常时应检查所用版式与局部覆盖。"}],"comparison":{"headers":["设置","文字","外框"],"rows":[["不自动调整","可超出边界","保持大小"],["溢出时缩小文字","按需要缩小","保持大小"],["调整形状大小以适应文字","保持字号","增大高度以容纳文字"]]},"pointGroups":null},{"q":11,"chapter":5,"section":"5.3","type":"单选","topic":"母版与主题","title":"幻灯片母版、版式与主题形成继承关系","trigger":"真题从全篇页脚、母版层级、多个版式和主题替换导致Logo缺失考查PowerPoint继承机制。","conclusion":"普通幻灯片基于所用版式，版式隶属于某组幻灯片母版；统一Logo或固定文字应修改相应母版，作用范围是使用这组母版的页面。","points":["一个母版可关联多个版式，一个演示文稿也可包含多组母版；不能把“本母版下全部页面”理解为文件中的全部页面。","只编辑某个版式影响使用该版式的页面；顶层母版提供其下版式共用的外观，单页或版式上的局部设置可能覆盖继承格式。","母版或版式中的Logo等对象在普通视图不能直接选中修改；要回到“视图→幻灯片母版”并找到实际提供该对象的层级。","修改已有版式的占位符结构后，现有幻灯片可能需要在普通视图重新应用该版式；不能把所有版式变化都理解为立即完整更新。","更换主题可能引入或替换母版；Logo缺失时检查该页实际使用的母版和版式，而不是只检查原先编辑过的母版。","仅让部分页面不显示继承的装饰图形，可启用“隐藏背景图形”；页面仍会放映，本页手动插入的图片不会因此自动隐藏。","PowerPoint区分幻灯片母版、讲义母版和备注母版；普通演示文稿至少有一组幻灯片母版，版式数量并非永远固定。","母版上的普通文本框可以显示固定标识；日期、页脚和编号占位符还需通过“页眉和页脚”启用。"],"boundary":"母版管理共用外观，不是逐页正文编辑器；普通视图不能直接改继承的母版对象。固定文本框与自动页脚、日期和编号字段也不能混为一谈。","version":"已转换为PowerPoint 2016","id":"y2020q11","sources":[{"year":2020,"q":11,"type":"单选"},{"year":2023,"q":63,"type":"操作"},{"year":2024,"q":35,"type":"判断"},{"year":2025,"q":60,"type":"分析"},{"year":2021,"q":54,"type":"操作","page":9}],"keys":["2020-11","2023-63","2024-35","2025-60","2021-54"],"comparison":{"headers":["修改位置","影响范围","典型用途"],"rows":[["顶层幻灯片母版","使用该母版的页面","共用Logo、字体和背景"],["某个版式","使用该版式的页面","标题和内容占位符布局"],["普通幻灯片","当前选定页或对象","本页正文、局部格式"]]},"pointGroups":[{"title":"母版、版式与页面的继承范围","indices":[0,1,6]},{"title":"找到对象来源并重新应用版式","indices":[2,3]},{"title":"主题变化与背景图形隐藏","indices":[4,5]},{"title":"固定文字与动态页脚字段","indices":[7]}],"related":[{"id":"y2020q53","label":"只给选定幻灯片应用主题","reason":"应用另一主题可能改变母版与版式归属，统一Logo缺失时应检查页面实际继承链。"},{"id":"y2024q65","label":"页眉和页脚对话框可隐藏标题页编号","reason":"母版中的编号占位符还需在页眉和页脚对话框启用，存在对象不等于页面显示。"},{"id":"y2020q54","label":"设置背景图片、透明度并应用到全部幻灯片","reason":"隐藏背景图形、背景填充和母版对象是不同层次，不能用更换背景替代所有共用设计。"}]},{"q":53,"chapter":5,"section":"5.3","type":"操作","topic":"主题","title":"只给选定幻灯片应用主题","trigger":"题目要求仅改变第一张幻灯片的主题。","conclusion":"先在缩略图窗格选择目标页，再右击主题缩略图并选择“应用于选定幻灯片”，才能明确限定主题的应用范围。","points":["按住Ctrl可选择不相邻幻灯片；应观察缩略图的选中边框，而不是只看中央正在显示哪一页。","直接单击主题通常会影响整套演示文稿；仅选中一页不能代替“应用于选定幻灯片”命令。","主题统一控制颜色、字体和效果，与只更改背景颜色或背景图片不是同一动作。","同一文稿可以使用不同主题，每组主题对应相关母版和版式；添加第二组母版后，已有页面还需使用它的版式才会采用相应设计。","不同主题可满足局部任务要求，但使用过多会降低整套文稿的一致性。"],"boundary":"“重设幻灯片”恢复当前版式相关的占位符位置和格式，不负责更换主题，也不会删除已加入的内容。","version":"已转换为PowerPoint 2016","id":"y2020q53","sources":[{"year":2020,"q":53,"type":"操作"}],"keys":["2020-53"],"comparison":{"headers":["操作","改变什么"],"rows":[["应用于选定幻灯片","所选页使用的主题"],["只改背景","所选页的背景填充"],["重设幻灯片","恢复当前版式的占位符布局和格式"]]},"related":[{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"局部主题会对应相关母版和版式，页面只有使用相应版式才会继承该组设计。"},{"id":"y2020q54","label":"设置背景图片、透明度并应用到全部幻灯片","reason":"主题同时控制颜色、字体和效果，背景图片只改变背景填充，作用范围要分别确认。"}],"pointGroups":[{"title":"先选目标页并限定主题应用范围","indices":[0,1]},{"title":"主题内容、母版归属与整体一致性","indices":[2,3,4]}]},{"q":54,"chapter":5,"section":"5.3","type":"操作","topic":"背景图片","title":"设置背景图片、透明度并应用到全部幻灯片","trigger":"真题从图片或纹理填充、偏移、透明度和全部应用考查幻灯片背景。","conclusion":"从“设计→设置背景格式”选择图片或纹理填充，调整透明度及相应填充参数；只有使用“全部应用”才把背景推广到整套幻灯片。","points":["背景填充不是普通图片对象，不会出现在选择窗格，也不能像页内图片一样直接选择并拖动。","图片或纹理填充可从图片来源插入图片，也可选择信纸等内置纹理；需要平铺时再设置平铺偏移等参数。","透明度用于调整背景可见程度，修改后应检查正文对比度和可读性。","默认设置作用于当前页；关闭背景窗格会保留当前修改，但不等于已经应用到所有页。","“全部应用”推广到所有页；“重置背景”用于恢复背景格式，不是确认或保存操作。"],"boundary":"插入普通图片并置于底层仍是可选对象，也不会自动覆盖所有幻灯片；更改背景填充并不等于更换完整主题。","version":"已转换为PowerPoint 2016","id":"y2020q54","sources":[{"year":2020,"q":54,"type":"操作"},{"year":2024,"q":64,"type":"操作"},{"year":2022,"q":65,"type":"操作"}],"keys":["2020-54","2024-64","2022-65"],"related":[{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"普通视图选不中的内容可能来自母版或背景，两者修改入口和继承范围不同。"},{"id":"y2020q53","label":"只给选定幻灯片应用主题","reason":"更改背景不等于更换主题；局部与全局应用都要按具体命令确认范围。"},{"id":"y2026q53","label":"更改图片可保留对象的大部分效果","reason":"普通图片能更改来源并保留对象效果，背景填充没有可选的页内图片对象。"}],"pointGroups":[{"title":"背景填充类型与透明度","indices":[0,1,2]},{"title":"当前页、全部应用与重置背景","indices":[3,4]}]},{"q":55,"chapter":5,"section":"5.4","type":"操作","topic":"切换与动作","title":"幻灯片切换、换片条件、对象动画与动作跳转","trigger":"真题从手动/定时换片、动画顺序和鼠标悬停跳转考查PowerPoint动态效果。","conclusion":"切换控制整页之间的过渡，动画控制页内对象，动作或超链接可跳到目标页；效果持续时间、动画开始条件和自动换片时间必须分别设置。","points":["切换属于将要进入的页面：修改第2页到第3页的过渡应选第3页；一页同时只有一个切换效果，重新选择效果会替换原切换。","切换“持续时间”控制过渡本身耗时，数值越大通常越慢；“设置自动换片时间”控制何时前进，不能互换。","“单击鼠标时”与自动换片条件可同时启用；允许单击时，可以在自动换片前主动前进。微软说明自动换片计时在本页最后一个动画或其他效果结束后开始。","动画窗格的前后顺序、开始方式、延迟和持续时间共同决定播放过程；位于第2行不代表一定等第1行结束后才运行。","“单击时”等待放映单击；“与上一动画同时”可与前一效果并行；“上一动画之后”等待前一效果结束。延迟从相应开始条件满足时计算。","一个对象可通过“添加动画”保留已有动画并新增效果；直接从动画库重新选效果可能替换原效果。“预览”只用于查看效果，“持续时间”控制效果本身耗时。","普通“单击时”不要理解为必须点击该对象；指定点击某个对象才播放，需要设置相应动画触发器。","动作设置可分别响应鼠标单击和鼠标悬停；动作、超链接和放映导航可以真正跳到目标幻灯片，包括非相邻页面。","对象动画改变对象的进入、强调、退出或运动方式，不负责指定另一页为跳转目标；应在放映中实际触发并核对目标内容。","切换声音可使用受支持的声音文件；同一节内各页仍可采用不同切换效果。“全部应用”会推广到整套演示文稿。"],"boundary":"定时值越大不等于切换效果越慢；动画窗格顺序不等于全部效果逐个串行；对象动画也不能代替动作或超链接的目标页跳转。","id":"merged-11","sources":[{"year":2020,"q":55,"type":"操作"},{"year":2023,"q":25,"type":"多选"},{"year":2025,"q":54,"type":"操作"},{"year":2025,"q":55,"type":"操作"},{"year":2026,"q":10,"type":"单选"},{"year":2022,"q":26,"type":"多选"},{"year":2021,"q":11,"type":"单选","page":3},{"year":2021,"q":12,"type":"单选","page":3}],"keys":["2020-55","2023-25","2025-54","2025-55","2026-10","2022-26","2021-11","2021-12"],"comparison":{"headers":["设置","作用对象","决定什么"],"rows":[["切换持续时间","进入一页时的过渡","过渡执行多久"],["自动换片时间","当前页的放映过程","何时自动前进"],["动画开始、延迟、持续时间","页内对象效果","何时开始、等待多久、执行多久"],["动作或超链接","可点击或悬停的对象","触发后跳到哪里"]]},"pointGroups":[{"title":"整页切换与换片","indices":[0,1,2,9]},{"title":"页内对象动画","indices":[3,4,5,6]},{"title":"动作与跳转","indices":[7,8]}],"related":[{"id":"y2023q13","label":"排练计时会记录每张幻灯片的放映用时","reason":"排练计时记录每页用时，正式放映采用计时与切换效果持续时间是不同设置。"},{"id":"y2026q55","label":"从自定义放映中移除不等于删除幻灯片","reason":"动作可进入自定义放映并返回主放映，需要先建立正确的页面清单与顺序。"},{"id":"merged-12","label":"保留图表结构才能按系列或类别动画","reason":"图表对象的动画分组取决于是否保留系列和类别结构，图片只能整体播放。"}]},{"q":64,"chapter":5,"section":"5.4","type":"综合","topic":"图表动画","title":"保留图表结构才能按系列或类别动画","trigger":"两道连续题考查Excel图表粘贴到PowerPoint后如何分部分播放。","conclusion":"要按系列或类别设置图表动画，粘贴时必须保留可编辑的图表结构，再在效果选项中选择分组方式。","points":["粘贴为图片后只能把整张图作为一个对象播放。","可按系列、类别或系列中的元素等方式组织动画。","链接数据便于源表更新，嵌入数据便于文件独立携带。","系列对应图例中的各组数据；类别通常对应横轴标签。“按系列”是一整组依次出现，“按类别”是同一横轴类别下的各系列一起出现。"],"boundary":"保留结构与保留源格式不是同一件事；应同时检查粘贴类型和动画分组。","version":"已转换为Office 2016","id":"merged-12","sources":[{"year":2020,"q":64,"type":"综合"},{"year":2020,"q":65,"type":"综合"}],"keys":["2020-64","2020-65"],"related":[{"id":"y2020q59","label":"切换图表的行与列","reason":"按系列或类别播放前，先用图例与横轴确认两者对应的数据维度。"},{"id":"y2022q69","label":"链接Excel表格可随源数据更新，嵌入保留独立副本","reason":"链接决定源数据能否更新，嵌入决定是否带独立副本；它们与保留外观不同。"},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"保留图表结构后还需设置对象动画的开始条件、顺序及持续时间。"}]},{"q":13,"chapter":5,"section":"5.5","type":"单选","topic":"排练计时","title":"排练计时会记录每张幻灯片的放映用时","trigger":"题目辨析PowerPoint排练计时的计时显示和保存结果。","conclusion":"排练计时记录当前页用时和累计用时；结束时保留才保存计时，正式放映是否自动前进还取决于是否启用这些时间。","points":["选择“幻灯片放映→排练计时”后开始计时；暂停期间不累计，继续后恢复记录。","换页后当前页计时重新开始，累计时间继续增长；每张幻灯片分别记录自己的用时。","排练结束时可选择保留或丢弃本次记录；保留后可在浏览视图查看各页时长。","保存后仍可在“切换”中修改单页自动换片时间；排练用时与切换效果持续时间不是同一概念。","“设置幻灯片放映”中选择手动可暂时忽略已保存计时；切回使用已有计时才恢复按计时自动前进。","Office 2016录制放映可记录旁白、墨迹和计时；排练计时不能简单等同于录制全部内容，也不要套用新版摄像头录制界面。"],"boundary":"记录、保存和正式放映采用计时是三个状态；关闭使用计时不等于删除已保存时长，保存排练计时也不会立即开始正式自动放映。","id":"y2023q13","sources":[{"year":2023,"q":13,"type":"单选"},{"year":2021,"q":55,"type":"操作","page":9}],"keys":["2023-13","2021-55"],"comparison":{"headers":["阶段","可见结果"],"rows":[["排练记录","当前页及累计时间增长"],["保留计时","每页时长成为已保存设置"],["正式放映使用计时","按已保存时间自动前进"],["正式放映设为手动","保留时长但暂不自动前进"]]},"related":[{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"每页停留用时与过渡效果持续时间不同，自动换片还需核对最后一个动画及换片条件。"},{"id":"y2020q10","label":"浏览、普通、备注页和阅读视图的用途","reason":"保留排练计时后可在浏览视图查看各页时长，再核对页面顺序与整体节奏。"},{"id":"y2023q35","label":"PowerPoint音频可跨幻灯片播放，视频通常停留在所在页","reason":"音频跨页播放与单页视频归属会影响排练节奏，媒体设置需与换片时间一起核对。"}],"pointGroups":[{"title":"排练、累计与保存各页计时","indices":[0,1,2]},{"title":"正式放映是否采用已保存时间","indices":[3,4]},{"title":"排练计时与录制放映的区别","indices":[5]}]},{"q":35,"chapter":5,"section":"5.5","type":"判断","topic":"音视频播放","title":"PowerPoint音频可跨幻灯片播放，视频通常停留在所在页","trigger":"题目判断插入的视频是否既能裁剪又能跨多张幻灯片连续播放。","conclusion":"PowerPoint2016可裁剪本地插入的音频和视频；音频可跨幻灯片播放，普通嵌入视频通常在离开其所在幻灯片时停止。","points":["“在后台播放”会为音频组合跨幻灯片、循环等常用设置。","视频播放选项可控制自动/单击开始、全屏和循环。","裁剪只改变媒体使用的起止时间，不改变页面归属。选中本地插入的视频后，用视频工具→播放→裁剪视频设置起止点；在线插入的视频不支持PowerPoint的这套裁剪功能，应先确认媒体来源。","PowerPoint 2016可在“音频工具→播放”选择跨幻灯片播放，并按需启用“循环播放，直到停止”；“播完返回开头”不是循环播放。"],"boundary":"不要把音频的“跨幻灯片播放”选项套到视频；若需跨页视觉连续，应重新设计媒体或放映结构。","id":"y2023q35","sources":[{"year":2023,"q":35,"type":"判断"},{"year":2022,"q":63,"type":"操作"}],"keys":["2023-35","2022-63"],"related":[{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"媒体开始方式与页面自动换片条件共同影响播放过程，不能把切换时间当作媒体时长。"},{"id":"y2023q13","label":"排练计时会记录每张幻灯片的放映用时","reason":"用排练计时核对讲解和媒体节奏，但记录时长不等于录制全部旁白与内容。"}],"pointGroups":null},{"q":65,"chapter":5,"section":"5.5","type":"操作","topic":"幻灯片编号","title":"页眉和页脚对话框可隐藏标题页编号","trigger":"题目要求给所有幻灯片编号，但不在标题幻灯片显示。","conclusion":"打开“插入→幻灯片编号”，勾选“幻灯片编号”和“标题幻灯片中不显示”，再单击“全部应用”；编号位置与样式由母版或版式控制。","points":["“应用”作用于当前选定幻灯片，“全部应用”作用于整个演示文稿。","编号占位符的位置和样式由版式或母版控制；母版中存在占位符，不等于已经在页面上启用编号。","标题幻灯片的识别与所用版式有关，不能机械地理解为永远只排除文件第1页。","“插入→日期和时间/页眉和页脚”中勾选日期和时间并选择“自动更新”，再“全部应用”，可加入日期字段；手输日期只是固定文字。","自动日期在打开或打印演示文稿时反映当前日期；固定日期保持输入的文字。","页脚文字须在“页眉和页脚”中勾选并填写；母版普通文本框中的固定标识不是同一类页脚字段。"],"boundary":"隐藏编号不会删除该幻灯片，也不会改变后续幻灯片的实际编号序列；直接在文本框输入“1”不会成为自动编号。","id":"y2024q65","sources":[{"year":2024,"q":65,"type":"操作"},{"year":2022,"q":73,"type":"综合"}],"keys":["2024-65","2022-73"],"related":[{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"编号与页脚的位置来自母版或版式，是否显示仍需在页眉和页脚中启用。"},{"id":"y2020q12","label":"删除幻灯片要选中缩略图，隐藏不等于删除","reason":"标题页不显示编号只改编号外观，隐藏页面改变常规放映资格，两者都不同于删页。"},{"id":"y2024q55","label":"在形状中放置光标后插入PAGE域","reason":"Word页码与PowerPoint编号都应使用动态字段，手输数字不会自动跟随页面变化。"}],"pointGroups":[{"title":"编号启用、母版位置与标题页例外","indices":[0,1,2]},{"title":"自动日期、固定日期与页脚文字","indices":[3,4,5]}]},{"q":55,"chapter":5,"section":"5.5","type":"操作","topic":"自定义放映","title":"从自定义放映中移除不等于删除幻灯片","trigger":"题目要求在自定义放映列表中取消某张幻灯片。","conclusion":"进入“自定义幻灯片放映”，编辑目标方案并从右侧清单移除目标页；这只改变方案中的引用，原幻灯片仍保留。","points":["自定义放映在当前文件中保存所需页面的引用及播放顺序，不是另存一份演示文稿。","左侧是演示文稿中的源幻灯片，选中后可添加到右侧“自定义放映中的幻灯片”清单。","右侧上移或下移只调整该方案的播放顺序，不改变普通视图中的真实页序。","从右侧清单移除只影响当前方案；源页仍能编辑，也能用于其他方案。","一个文件可建立多个自定义放映方案；编辑完成后选择正确方案并实际放映，核对页序和内容。","通过动作或超链接进入自定义放映时，可根据任务设置“放映并返回”，使辅助放映结束后返回主放映。"],"boundary":"从清单移除、删除整个方案和在普通视图删除源幻灯片是不同操作；取消编辑应保留此前已保存的方案。","id":"y2026q55","sources":[{"year":2026,"q":55,"type":"操作"},{"year":2022,"q":74,"type":"综合"}],"keys":["2026-55","2022-74"],"related":[{"id":"y2020q12","label":"删除幻灯片要选中缩略图，隐藏不等于删除","reason":"移除方案引用、隐藏源页与删除源页分别改变不同对象，要按清单和缩略图位置判断。"},{"id":"y2025q10","label":"PowerPoint的节用于组织，导航最终定位幻灯片","reason":"节组织编辑结构，自定义放映组织播放路径，调整方案顺序不会重排普通视图的真实页序。"},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"通过动作或超链接进入辅助放映时，可设置放映并返回，核对真正的跳转目标。"}],"pointGroups":[{"title":"编辑方案引用与独立播放顺序","indices":[0,1,2,3]},{"title":"核对多个方案与放映并返回","indices":[4,5]}]},{"id":"syllabus-ppt-output","chapter":5,"section":"5.5","origin":"syllabus","topic":"考纲补充","title":"PPT先按交付目标选择打印、共享或导出","conclusion":"需要继续编辑时保留PPTX；PPSX通常以放映方式打开；固定页面阅读可导出PDF；需要连续播放的成片可导出视频。扩展名与具体保存/导出操作配合决定交付用途。","points":["文件→打印中，整页幻灯片便于逐页检查画面；讲义可在一张纸上放多张幻灯片；备注页包含当前幻灯片和演讲者备注；大纲侧重文本结构。","共享前核对目标：发送附件形成副本；共享云端链接仍指向同一文件，并需确认查看或编辑权限。导出后检查页数、字体、图片和超链接等关键结果。","视频导出需检查旁白、动画和幻灯片计时；PDF不会按放映方式执行全部动画和切换。"],"boundary":"交付文件能打开不等于所有动态效果都已保留；应按目标格式核对。","sources":[],"trigger":"依据山东省2026年专升本公共基础课考试要求补充；下方为教学示例。","related":[{"id":"y2023q45","label":"ppsx是PowerPoint放映文件扩展名","reason":"联系相邻知识理解作用范围"}]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
